import pytest
from target import match_parens


class TestMatchParensEmpty:
    """Test cases with empty strings."""

    def test_both_empty(self):
        """Two empty strings form a good string."""
        assert match_parens(['', '']) == 'Yes'

    def test_empty_with_balanced(self):
        """Empty string concatenated with balanced string."""
        assert match_parens(['', '()']) == 'Yes'

    def test_empty_with_unbalanced(self):
        """Empty string with unbalanced string cannot form good string."""
        assert match_parens(['', ')']) == 'No'

    def test_balanced_with_empty(self):
        """Balanced string with empty string."""
        assert match_parens(['()', '']) == 'Yes'


class TestMatchParensSingleCharacter:
    """Test cases with single character strings."""

    def test_open_then_close(self):
        """Single open followed by single close."""
        assert match_parens(['(', ')']) == 'Yes'

    def test_close_then_open(self):
        """Single close followed by single open works in reverse order."""
        assert match_parens([')', '(']) == 'Yes'

    def test_two_opens(self):
        """Two open parentheses cannot be balanced."""
        assert match_parens(['(', '(']) == 'No'

    def test_two_closes(self):
        """Two close parentheses cannot be balanced."""
        assert match_parens([')', ')']) == 'No'


class TestMatchParensBalancedTotal:
    """Test cases where total opens equal total closes."""

    def test_balanced_pairs(self):
        """Two already-balanced strings."""
        assert match_parens(['()', '()']) == 'Yes'

    def test_all_opens_then_all_closes(self):
        """All opens in first string, all closes in second."""
        assert match_parens(['(((', ')))']) == 'Yes'

    def test_multiple_pairs(self):
        """Multiple opening and closing pairs."""
        assert match_parens(['((', '))']) == 'Yes'

    def test_complex_balanced_first(self):
        """Complex nested first string with simple second."""
        assert match_parens(['(())', '()']) == 'Yes'

    def test_nested_in_second(self):
        """Opens in first, nested closes in second."""
        assert match_parens(['(', '())']) == 'Yes'

    def test_longer_concatenation(self):
        """Longer string that balances."""
        assert match_parens(['()()(', ')']) == 'Yes'

    def test_complex_valid_pair(self):
        """Two opens with nested structure in second."""
        assert match_parens(['((', '()))']) == 'Yes'

    def test_close_prefix_with_large_suffix(self):
        """Close at start of first string, many opens in second."""
        assert match_parens([')', '(((()))']) == 'Yes'

    def test_docstring_example_1(self):
        """First example from docstring."""
        assert match_parens(['()(', ')']) == 'Yes'


class TestMatchParensImbalancedTotal:
    """Test cases where opens do not equal closes in total."""

    def test_too_many_opens(self):
        """More opens than closes overall."""
        assert match_parens(['(()', '(']) == 'No'

    def test_too_many_closes(self):
        """More closes than opens overall."""
        assert match_parens(['(', ')))']) == 'No'

    def test_mixed_imbalanced(self):
        """Mixed pattern with unequal total."""
        assert match_parens(['()(', '))']) == 'No'

    def test_unbalanced_by_one_open(self):
        """Exactly one extra open."""
        assert match_parens(['(((())))', ')']) == 'No'


class TestMatchParensNegativePrefix:
    """Test cases where valid ordering requires avoiding negative prefix balance."""

    def test_close_in_first_string(self):
        """First string has close that creates negative prefix."""
        assert match_parens(['()', ')(']) == 'No'

    def test_both_start_with_close(self):
        """Both strings start with close parenthesis."""
        assert match_parens(['))', '((']) == 'No'

    def test_early_unmatched_close(self):
        """Unmatched close before final balance."""
        assert match_parens(['())(', '()']) == 'No'

    def test_close_first_in_both(self):
        """Neither order avoids early negative balance."""
        assert match_parens([')', ')']) == 'No'


class TestMatchParensDocstringExamples:
    """Test the explicit examples from the function docstring."""

    def test_docstring_example_yes(self):
        """Example that should return 'Yes'."""
        assert match_parens(['()(', ')']) == 'Yes'

    def test_docstring_example_no(self):
        """Example that should return 'No'."""
        assert match_parens([')', ')']) == 'No'
